using Microsoft.AspNetCore.Identity;

namespace IdleHold.Api.Accounts;

/// <summary>
/// Identity's user validator, except for guests. A guest has no e-mail, which the default validator
/// refuses because e-mails are required and unique; its user name is generated by the server, and the
/// database's unique index on user names still applies. Once a guest signs up, the full rules run.
/// </summary>
public sealed class AccountValidator(IdentityErrorDescriber errors) : UserValidator<Account>(errors)
{
    public override Task<IdentityResult> ValidateAsync(UserManager<Account> manager, Account user) =>
        user.IsAnonymous ? Task.FromResult(IdentityResult.Success) : base.ValidateAsync(manager, user);
}
